package com.quransunah.app.fonts

import android.content.Context
import dagger.hilt.android.qualifiers.ApplicationContext
import java.io.InputStream
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Per-word glyph strings for the 604 coloured QPC V4 page fonts (`fonts/qcf4/pN.ttf`).
 *
 * `quran_unified.db` keeps the 47-face `qpc_ligature` codes (still used for marker detection);
 * the page fonts use Quran.com v4 per-page codes. `assets/json/qpc-v4-glyphs.tsv` is generated by
 * `tools/build_v4_glyph_map.py` (word_id → hex code points) and verified against the reference word list.
 * Loaded once, lazily (~84k entries), on the first caller's thread (repositories run on IO).
 */
@Singleton
class QpcV4Glyphs @Inject constructor(
    @ApplicationContext private val context: Context,
) {
    init { instance = this }

    private val table: Array<String?> by lazy {
        context.assets.open(ASSET).use { parse(it) }
    }

    /** v4 glyph string for [wordId], or null if unknown. */
    fun forWord(wordId: Int): String? = table.getOrNull(wordId)

    companion object {
        const val ASSET = "json/qpc-v4-glyphs.tsv"

        /** Set when Hilt creates the singleton; used by plain mapping functions (e.g. `WordEntity.toWordRecord`). */
        @Volatile var instance: QpcV4Glyphs? = null
            private set

        fun parse(input: InputStream): Array<String?> {
            val rows = ArrayList<Pair<Int, String>>(84_000)
            var max = 0
            input.bufferedReader().forEachLine { line ->
                if (line.isEmpty() || line[0] == '#') return@forEachLine
                val tab = line.indexOf('\t')
                if (tab <= 0) return@forEachLine
                val id = line.substring(0, tab).toInt()
                val sb = StringBuilder(4)
                for (hex in line.substring(tab + 1).split('+')) sb.appendCodePoint(hex.trim().toInt(16))
                rows += id to sb.toString()
                if (id > max) max = id
            }
            val out = arrayOfNulls<String>(max + 1)
            for ((id, s) in rows) out[id] = s
            return out
        }
    }
}
